        "description": "ଗଚ୍ଛିବୋଲି ଛକ ନିକଟରେ ରାସ୍ତା ପ୍ରସସ୍ତୀକରଣ କାର୍ଯ୍ୟ ଅଧାରୁ ବନ୍ଦ ହୋଇଯାଇଛି। ରାସ୍ତାରେ ବାରିକେଡ୍ ରହିଯିବା କାରଣରୁ ବ୍ୟସ୍ତବହୁଳ ସମୟରେ ପ୍ରତିଦିନ ଟ୍ରାଫିକ ଜାମ ହେଉଛି। ଜିଏଚଏମସି (GHMC) ଏବଂ ଏନଏଚଏଆଇ (NHAI) କୁ ବହୁତ ଅଭିଯୋଗ କରାଯାଇଥିଲେ ମଧ୍ୟ କୌଣସି ଉତ୍ତର ମିଳିନାହିଁ।"
