        "summary": "ଗ୍ରେଟର ହାଇଦ୍ରାବାଦରେ ୫୦୦ କିଲୋମିଟର ରାସ୍ତାକୁ ଲକ୍ଷ୍ୟ କରି ପ୍ରମୁଖ ସଡ଼କ ଭିତ୍ତିଭୂମି ବିକାଶ କରାଯିବ। ଓଆରଆର (ORR) ସର୍ଭିସ ରୋଡ୍ ଏବଂ କଲୋନୀର ଆଭ୍ୟନ୍ତରୀଣ ରାସ୍ତା ଉପରେ ଧ୍ୟାନ ଦିଆଯିବ।"
