        "title": "ଦଳ ବଦଳ ବିରୋଧୀ ଆଇନ: ସୁପ୍ରିମକୋର୍ଟ ଆସନ୍ତା ସପ୍ତାହରେ ତେଲେଙ୍ଗାନା ବିଆରଏସ (BRS) ର ଆବେଦନ ଶୁଣାଣି କରିବେ",
        "summary": "୧୦ଟି ବିଆରଏସ-ରୁ-କଂଗ୍ରେସ ଦଳ ବଦଳ ମାମଲା ବିଚାରାଧୀ ରହିଛି। ବାଚସ୍ପତିଙ୍କ ବିଳମ୍ବିତ ଅଯୋଗ୍ୟତା ଘୋଷଣା ପ୍ରକ୍ରିୟାକୁ କୋର୍ଟ ଯାଞ୍ଚ କରିବେ।"
