        "summary": "ସହରୀ ରୁଟ୍ ଗୁଡ଼ିକ ଲାଭଦାୟକ କିନ୍ତୁ ୪୦% ଗ୍ରାମୀଣ ରୁଟ୍ କ୍ଷତିରେ ଚାଲିଛି। ବନ୍ଦ କରିବା ପରିବର୍ତ୍ତେ ରୁଟ୍ ର ଯୁକ୍ତିସଙ୍ଗତକରଣ ପାଇଁ ୟୁନିଅନ୍ ଦାବି କରିଛି।"
