        "summary": "ଜବରଦଖଲ ଉଚ୍ଛେଦକୁ ଆହ୍ୱାନ କରୁଥିବା ଆବେଦନ ଉପରେ ହାଇକୋର୍ଟ ନୋଟିସ ଜାରି କରିଛନ୍ତି। ସରକାର ଯୁକ୍ତି ବାଢ଼ିଛନ୍ତି ଯେ ପ୍ରଦୂଷଣ ମୁକ୍ତ କରିବା ପ୍ରାଥମିକତା ଅଟେ।"
